from urllib.parse import quote

from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class BBv1HttpClient(HttpClient):
    """ This class provides a client for the BB v1 API. """
    def __init__(self, base_url, connection_alias):
        super(BBv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/bb/v1"

    def get_rnic_sync_status(self, rnic_runtime_distname, timeout=30):
        endpoint = f"/sync/status/{quote(rnic_runtime_distname, safe='')}"
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def reset_rannic(self, timeout=30, rannic_r_dn=None, graceful_cell_shutdown=False):
        endpoint = '/ran-nic/operations/reset'
        payload = {"rannicRDn": rannic_r_dn, "reason": "Manual reboot", "gracefulCellShutdown": graceful_cell_shutdown}

        return self._send_post_request(endpoint=endpoint, json=payload, timeout=timeout)

    def get_reset_rannic_operation_status(self, operation_id, timeout=30, ):
        endpoint = f'/ran-nic/operations/reset/{operation_id}'

        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_reset_rannic_operation(self, operation_id, timeout=30):
        endpoint = f'/ran-nic/operations/reset/{operation_id}'

        headers = {
            "accept": "*/*"
        }

        self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def post_rannic_test_clock_configure(self, rannic_r_dn, intended_test_clock_output=None, intended_frame_clock_output=None,
                                         timeout=30):
        endpoint = f"/sync/test-clocks/{quote(rannic_r_dn, safe='')}"
        payload = {}
        if intended_test_clock_output is not None:
            payload["intendedTestClockOutput"] = intended_test_clock_output
        if intended_frame_clock_output is not None:
            payload["intendedFrameClockOutput"] = intended_frame_clock_output
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json"
            }
        if intended_test_clock_output or intended_frame_clock_output:
            return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)
        else:
             raise ValueError("At least one of the arguments intended_test_clock_output, intended_frame_clock_output should not be None!")

    def get_rannic_test_clock_operation_status(self, operation_id, timeout=30):
        endpoint = f'/sync/test-clocks/operations/{operation_id}'
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def delete_rannic_test_clock_operation(self, operation_id, timeout=30):
        endpoint = f'/sync/test-clocks/operations/{operation_id}'
        headers = {
            "accept": "*/*"
        }

        self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_rannic_test_clocks_status(self, timeout=30):
        endpoint = '/sync/test-clocks'
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
